fn main() {
    let mut count = 3;
    while count > 0 {
        println!("tick {count}");
        count -= 1;
    }
    println!("liftoff");

    let mut partial = 0;
    for n in 1..5 {
        partial += n;
    }
    println!("1..5 sums to {partial}");

    let mut whole = 0;
    for n in 1..=5 {
        whole += n;
    }
    println!("1..=5 sums to {whole}");
}

fn main() {
    let scores = [4, 9, 7];
    for s in scores {
        if s < 5 {
            continue;
        }
        println!("good score: {s}");
    }

    let mut pairs = 0;
    for a in 1..=2 {
        for b in 1..=3 {
            if a == b {
                continue;
            }
            pairs += 1;
        }
    }
    println!("pairs: {pairs}");
}

